from pathlib import Path
import hashlib

source_path = Path('tools/ats_question_triage.py')
regression_path = Path('tests/test_ats_question_triage_autonomous.py')
immutable_path = Path('tests/test_ats_question_triage.py')
expected_blob = '8b4d37223ee08c0add0d5b349875a8e8983cd0d9'


def git_blob_sha1(data):
    header = b'blob ' + str(len(data)).encode('ascii') + b'\0'
    return hashlib.sha1(header + data).hexdigest()


immutable_before = immutable_path.read_bytes()
if git_blob_sha1(immutable_before) != expected_blob:
    raise RuntimeError('Immutable test Git blob identity mismatch')

if not source_path.is_file() or not regression_path.is_file():
    raise RuntimeError('Expected completed ATS implementation and regressions are missing')

original_source = source_path.read_text(encoding='utf-8')
original_tests = regression_path.read_text(encoding='utf-8')

old = '    if bool(field.get("ambiguous")) or not question:\n'
new = '    if field.get("ambiguous", False) is not False or not question:\n'

if original_source.count(old) != 1:
    raise RuntimeError('Expected ambiguity classification expression not found exactly once')

if 'mismatched_contact_control' not in original_source:
    raise RuntimeError('Previously completed contact-control safeguards are missing')

if 'def test_mismatched_contact_controls_require_review(' not in original_tests:
    raise RuntimeError('Previously completed autonomous regressions are missing')

if 'def test_nonboolean_ambiguity_metadata_requires_review(' in original_tests:
    raise RuntimeError('Requested ambiguity regressions already exist')

additional_tests = '''

@pytest.mark.parametrize('ambiguous', [
    None,
    0,
    0.0,
    '',
    [],
    {},
    (),
    'false',
    'False',
    '0',
    'no',
    1,
    True,
])
def test_nonboolean_ambiguity_metadata_requires_review(ambiguous):
    result = classify_field(
        {
            'question': 'Email',
            'label': 'Email',
            'type': 'email',
            'ambiguous': ambiguous,
        },
        {'email'},
    )
    assert result == {
        'status': 'human_review',
        'reason': 'ambiguous_question',
    }


@pytest.mark.parametrize('question,kind,key', [
    ('Full name', 'text', 'full_name'),
    ('Email', 'email', 'email'),
    ('Phone', 'tel', 'phone'),
    ('LinkedIn', 'url', 'linkedin'),
    ('GitHub', 'url', 'github'),
])
@pytest.mark.parametrize('include_flag', [False, True])
def test_false_or_missing_ambiguity_preserves_candidates(
    question, kind, key, include_flag
):
    field = {
        'question': question,
        'label': question,
        'type': kind,
    }
    if include_flag:
        field['ambiguous'] = False
    result = classify_field(field, {key})
    assert result == {
        'status': 'verified_candidate',
        'profile_key': key,
    }


def test_malformed_ambiguity_remains_review_even_without_verified_fact():
    result = classify_field(
        {
            'question': 'Email',
            'label': 'Email',
            'type': 'email',
            'ambiguous': None,
        },
        set(),
    )
    assert result == {
        'status': 'human_review',
        'reason': 'ambiguous_question',
    }


def test_mixed_ambiguity_metadata_preserves_triage_order():
    fields = [
        {
            'question': 'Email',
            'label': 'Email',
            'type': 'email',
            'ambiguous': False,
        },
        {
            'question': 'Email',
            'label': 'Email',
            'type': 'email',
            'ambiguous': None,
        },
        {
            'question': 'Phone',
            'label': 'Phone',
            'type': 'tel',
            'ambiguous': [],
        },
        {
            'question': 'GitHub',
            'label': 'GitHub',
            'type': 'url',
        },
        {
            'question': 'LinkedIn',
            'label': 'LinkedIn',
            'type': 'email',
            'ambiguous': False,
        },
    ]
    results = triage_fields(fields, {'email', 'phone', 'github', 'linkedin'})
    assert results == [
        {'status': 'verified_candidate', 'profile_key': 'email'},
        {'status': 'human_review', 'reason': 'ambiguous_question'},
        {'status': 'human_review', 'reason': 'ambiguous_question'},
        {'status': 'verified_candidate', 'profile_key': 'github'},
        {'status': 'human_review', 'reason': 'mismatched_contact_control'},
    ]


def test_malformed_ambiguity_never_returns_candidate_data():
    result = classify_field(
        {
            'question': 'Full name',
            'label': 'Full name',
            'type': 'text',
            'ambiguous': {},
        },
        {'full_name'},
    )
    assert result == {
        'status': 'human_review',
        'reason': 'ambiguous_question',
    }
    assert 'profile_key' not in result
    assert 'answer' not in result
    assert 'value' not in result
'''

updated_source = original_source.replace(old, new, 1)
updated_tests = original_tests.rstrip('\n') + '\n' + additional_tests

compile(updated_source, str(source_path), 'exec')
compile(updated_tests, str(regression_path), 'exec')

if immutable_path.read_bytes() != immutable_before:
    raise RuntimeError('Immutable test changed before implementation')

source_written = False
tests_written = False
try:
    source_path.write_text(updated_source, encoding='utf-8')
    source_written = True
    regression_path.write_text(updated_tests, encoding='utf-8')
    tests_written = True
    if immutable_path.read_bytes() != immutable_before:
        raise RuntimeError('Immutable test changed during implementation')
    if git_blob_sha1(immutable_path.read_bytes()) != expected_blob:
        raise RuntimeError('Immutable test Git blob identity changed')
except BaseException:
    if source_written:
        source_path.write_text(original_source, encoding='utf-8')
    if tests_written:
        regression_path.write_text(original_tests, encoding='utf-8')
    raise
